public class SafeNum {
    public static Double toNumber(String text) {
        return null;
    }
}

exercises.solution:
public class SafeNum {
    public static Double toNumber(String text) {
        try {
            return Double.parseDouble(text.trim().replace(",", "."));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

